{
  "primary_intent": "project_science_question",
  "reasoning_effort": 1,
  "direct_answer": null,
  "needs_clarification": false,
  "clarification_reason": null,
  "entities": {
    "project": "SUMO1",
    "experimental_context": "phage display",
    "reagents": [
      "CM13d3",
      "M13KO7"
    ]
  },
  "inventory_search": {
    "normalized_query": null,
    "candidate_terms": [],
    "aliases": [],
    "search_mode": null
  },
  "protocol_candidates": [],
  "reasoning_summary": "The user is asking for an explanation of two helper phages used in a specific project context and how they may affect phage display outcomes."
}

{
  "trace_sentence": "I am defining stop conditions for a project-first science reasoning loop about the two helper phages.",
  "exit_criteria": [
    {
      "id": "identity_confirmed",
      "must_have": [
        "Project-linked records identify exactly what CM13d3 was in the experiment, including supplier or construct name and any recorded genotype or resistance markers.",
        "Project-linked records identify exactly what M13KO7 was in the experiment, including supplier or construct name and any recorded genotype or resistance markers.",
        "The loop has verified whether both names refer to the same helper phage family or to materially different helper phages."
      ],
      "continue_if_missing": [
        "Continue if either phage identity is ambiguous, misspelled, or only inferred from memory.",
        "Continue if the record does not show which phage was actually used in each rescue or amplification step."
      ],
      "limitation_qualified_ok": "A limitation-qualified answer is acceptable only if the response states that the phage identity is provisional and that any downstream interpretation depends on confirming the exact construct from the project record."
    },
    {
      "id": "mechanism_compared",
      "must_have": [
        "The loop has compared the helper phages on the features that matter for phage display: packaging support, display burden on the phagemid, expected phage yield, and likely display valency or bias.",
        "The loop has identified at least one evidence-backed reason the helper phages could change display output, not just a name-level difference."
      ],
      "continue_if_missing": [
        "Continue if the loop only has general statements like 'they are different helper phages' without mechanism.",
        "Continue if the mechanism is speculative and not tied to either internal records or reliable external sources."
      ],
      "limitation_qualified_ok": "If exact mechanistic detail cannot be confirmed, an answer may still stop when it clearly separates confirmed facts from likely effects and labels the mechanism as inferred."
    },
    {
      "id": "result_impact_established",
      "must_have": [
        "The loop has a concrete statement of how the difference would affect phage display results, such as changes in enrichment, clone recovery, helper-phage background, infectivity, display density, or recovery bias.",
        "The statement distinguishes directionality when supported by evidence, for example whether one helper phage is expected to favor higher helper phage contamination or lower display density."
      ],
      "continue_if_missing": [
        "Continue if the loop cannot say whether the effect would increase, decrease, or not materially change the display outcome.",
        "Continue if the effect is only described qualitatively as 'better' or 'worse' without mapping to an assay outcome."
      ],
      "limitation_qualified_ok": "A limited answer is acceptable if it says the effect on results is likely assay-dependent and gives the most probable direction with a clear caveat."
    },
    {
      "id": "project_first_checked",
      "must_have": [
        "Project-linked records have been checked first for the exact phage names, protocol context, and any notes about why that helper phage was chosen.",
        "External literature is used only to fill gaps after project-linked evidence is exhausted."
      ],
      "continue_if_missing": [
        "Continue if the answer is based on external literature before checking internal records.",
        "Continue if internal records exist but were not consulted for protocol context or actual usage."
      ],
      "limitation_qualified_ok": "A limitation-qualified answer is acceptable if internal evidence is incomplete and the response explicitly says so while using external literature only as fallback support."
    },
    {
      "id": "evidence_sufficient_to_stop",
      "must_have": [
        "There is enough evidence to answer the user's question in one of these forms: a direct comparison with mechanism and result impact, or a clearly labeled provisional comparison with stated uncertainties.",
        "No unresolved contradiction remains between records, notebook entries, inventory, or literature about which helper phage was used."
      ],
      "continue_if_missing": [
        "Continue if the evidence base conflicts, is incomplete, or does not support a confident comparison.",
        "Continue if the loop cannot connect the helper phage difference to a plausible impact on the specific phage display workflow used in the project."
      ],
      "limitation_qualified_ok": "Stop only if the final answer can clearly say either 'confirmed comparison' or 'best-supported provisional comparison' and explicitly note what remains unverified."
    }
  ]
}

entries.system_prompt:
You are Lab Agent, an AI assistant for a research lab app. Help users retrieve lab information, reason carefully about scientific questions, and stay explicit about uncertainty.

Scoped project: SUMO1.

Use only tools that are explicitly available in the current runtime. If a needed tool is unavailable, say so clearly instead of pretending it succeeded.

Intent: project_science_question

Reasoning effort: 1

Execution hints:
- Project: SUMO1 (1774128185432-96a318da61d208)
- Retrieval preference: internal_first_then_external.
- Project resolution must be established before project-specific reasoning.
- Keep internal evidence clearly separated from external evidence.
- Loop goal: I used CM13d3 and M13KO7 as the helper phage for phage display. What is the difference and how it will affect my phage display results
- Route summary: Start with the most targeted project-grounded evidence step and adapt from there only if a real gap remains.
- Preferred tools: inventory-lookup | record-lookup | protocol-matching
- Route suggestions are guidance only.
- Objective: I used CM13d3 and M13KO7 as the helper phage for phage display. What is the difference and how it will affect my phage display results
- Exit when: The current evidence directly supports the core answer to the clarified request.

The clarified execution request is provided separately as the session message.

1. You are inside a deterministic science reasoning loop.
2. At each assistant turn, either call exactly one tool or answer directly if you already have sufficient evidence.
3. Do not call more than one tool in a single assistant turn.
4. Prefer tools in the listed priority order and explain the answer only after sufficient evidence exists.
5. When you give the final answer, include enough detail to explain the conclusion, supporting evidence, and material caveats.
6. Do not compress the final answer to one or two sentences unless the user explicitly asked for brevity.
7. Treat any route plan as non-binding guidance; adapt when the actual evidence suggests a better next step.
8. If a tool result is weak or empty, choose a more targeted next tool on the following turn.
9. Do not fabricate project records, literature results, or computation outputs.
10. For project science questions, keep project context explicit and clearly separate internal evidence from external evidence.

You are participating in a stepwise tool loop.

At each turn, either request exactly one tool call or answer directly if the evidence is already sufficient.

Return JSON only in one of these forms:

{"assistant_text":"progress update","tool_call":{"name":"tool_name","arguments":{}}}

{"assistant_text":"grounded final answer","tool_call":null}

Never return more than one tool call in a single turn.

Available tools:
Tool: inventory-lookup
Description: Use this tool when the user needs to know whether a reagent, consumable, or personal inventory item exists locally, where it is stored, or how much is available. Prefer it for stock, location, container, quantity, and alias-based reagent lookup. Provide `query` for the main search text, and include `inventory_search` when the parser already extracted normalized candidate terms or search hints.
Input schema JSON:
{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "query": {
      "type": "string"
    },
    "limit": {
      "type": "integer",
      "minimum": 1,
      "maximum": 25
    },
    "inventory_search": {
      "$ref": "#/$defs/inventory_search"
    },
    "parser_payload": {
      "$ref": "#/$defs/parser_payload"
    }
  }
}

Tool: record-lookup
Description: Use this tool when the user is asking about stored lab records beyond raw inventory, such as projects, protocols, notebook entries, workflows, assays, gels, or linked historical context. Prefer it for 'what did we do last time', 'find the protocol record', or project-specific evidence retrieval. Provide `query` for the entity or topic to search, and pass `parser_payload` when parser entities can help narrow record matching.
Input schema JSON:
{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "query": {
      "type": "string"
    },
    "limit": {
      "type": "integer",
      "minimum": 1,
      "maximum": 25
    },
    "parser_payload": {
      "$ref": "#/$defs/parser_payload"
    }
  }
}

Tool: protocol-matching
Description: Use this tool to choose the best local protocol for a user-described activity before generating a notebook entry or protocol-driven draft. It ranks candidate protocols against parser hints, protocol names, aliases, purposes, and step overlap. Provide `protocol_candidates` when the parser or caller already identified likely names, and optionally provide `fallback_protocol` only when there is one specific protocol record that should be considered if ranked candidates are weak.
Input schema JSON:
{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "protocol_candidates": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "maxItems": 5
    },
    "fallback_protocol": {
      "$ref": "#/$defs/protocol_record"
    }
  }
}

Tool: notebook-generation
Description: Use this tool after protocol selection to generate a structured notebook draft from a selected protocol, project context, and known placeholder values. It fills placeholders conservatively, keeps unresolved placeholders visible, and can return follow-up questions when key details are missing. Provide `selected_protocol` when already known, `project` when a project has been resolved, and `pending_values` for explicit user-supplied placeholder answers.
Input schema JSON:
{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "selected_protocol": {
      "$ref": "#/$defs/protocol_record"
    },
    "project": {
      "$ref": "#/$defs/project_record"
    },
    "pending_values": {
      "$ref": "#/$defs/pending_values"
    }
  }
}

Tool: notebook-draft
Description: Use this tool to propose a likely next experiment and prepare a planned biology notebook draft for explicit confirmation. It should prefer workflow-downstream experiments and recent executed notebook progress, tolerate unresolved placeholders, and return a confirm-before-save draft instead of auto-creating the page.
Input schema JSON:
{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "project": {
      "$ref": "#/$defs/project_record"
    },
    "workflow_id": {
      "type": "string",
      "maxLength": 160
    },
    "protocol_candidates": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "maxItems": 5
    }
  }
}

Tool: python-sandbox
Description: Use this tool when the agent needs to write and run Python code to compute, transform, inspect, or generate artifacts in a controlled sandbox. The agent should supply complete runnable code in `code`, optionally stage input files in `files`, and request outputs through `readback_paths`. Inside the sandbox, `import enana_sandbox as sandbox` to read staged files and emit chat-renderable text or image outputs. Prefer this for deterministic analysis or file generation, not for calling local lab records that already have dedicated lookup tools.
Input schema JSON:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "code"
  ],
  "properties": {
    "code": {
      "type": "string",
      "minLength": 1,
      "maxLength": 40000
    },
    "timeout_ms": {
      "type": "integer",
      "minimum": 500,
      "maximum": 15000
    },
    "files": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/python_sandbox_file"
      },
      "maxItems": 32
    },
    "readback_paths": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1,
        "maxLength": 240
      },
      "maxItems": 20
    }
  }
}

Tool: sub-agent
Description: Use this tool to manage helper sub-agent sessions for multi-step or delegated work that should persist across turns. `create` starts a managed sub-agent with a system prompt and initial message, `message` sends a follow-up, `get` inspects one session, `list` shows active sessions, and `delete` removes a session. Use it when the agent needs a reusable delegated workspace rather than a one-shot tool execution.
Input schema JSON:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "action"
  ],
  "properties": {
    "action": {
      "type": "string",
      "enum": [
        "create",
        "message",
        "delete",
        "get",
        "list"
      ]
    },
    "agent_id": {
      "type": "string",
      "minLength": 1,
      "maxLength": 160
    },
    "name": {
      "type": "string",
      "maxLength": 160
    },
    "system_prompt": {
      "type": "string",
      "maxLength": 40000
    },
    "message": {
      "type": "string",
      "maxLength": 40000
    },
    "reason": {
      "type": "string",
      "maxLength": 240
    },
    "metadata": {
      "$ref": "#/$defs/sub_agent_metadata"
    }
  }
}

Tool: memory
Description: Use this tool to manage sparse long-term user memory across sessions. `recall` searches previously stored preferences, project names, workflow habits, or other stable context. `remember` stores or updates a structured memory record with `key`, `summary`, and optional `value`. `forget` removes matching memory entries. `list` enumerates stored memory, optionally filtered by category, project, or tags. Use it only for durable facts or preferences, not for replaying whole conversations.
Input schema JSON:
{
  "type": "object",
  "additionalProperties": false,
  "required": [
    "action"
  ],
  "properties": {
    "action": {
      "type": "string",
      "enum": [
        "recall",
        "remember",
        "forget",
        "list"
      ]
    },
    "id": {
      "type": "string",
      "maxLength": 160
    },
    "query": {
      "type": "string",
      "maxLength": 320
    },
    "category": {
      "type": "string",
      "maxLength": 120
    },
    "key": {
      "type": "string",
      "maxLength": 220
    },
    "summary": {
      "type": "string",
      "maxLength": 600
    },
    "value": {
      "anyOf": [
        {
          "type": "object"
        },
        {
          "type": "array"
        },
        {
          "type": "string"
        },
        {
          "type": "number"
        },
        {
          "type": "boolean"
        },
        {
          "type": "null"
        }
      ]
    },
    "project_name": {
      "type": "string",
      "maxLength": 220
    },
    "tags": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "maxItems": 12
    },
    "source": {
      "type": "string",
      "maxLength": 120
    },
    "limit": {
      "type": "integer",
      "minimum": 1,
      "maximum": 50
    },
    "record": {
      "$ref": "#/$defs/memory_record"
    }
  }
}

Tool: literature-search
Description: Use this tool when the user wants papers, references, recent literature, external evidence, or protein knowledgebase entries rather than a summary of one already-identified paper. Provide `query` when possible, and prefer short keyword or entity phrases instead of full-sentence prompts, for example `MAPK inhibitor resistance mechanism review` or `PD-1 ubiquitination stability`. Use `source` for one source, `sources` for an explicit multi-source batch, or leave them empty for scholarly-first auto mode. Auto mode searches literature sources first and only falls back to generic web search when those sources do not produce results. Prefer `pubmed`, `crossref`, and `europe_pmc` for papers, `uniprot` for protein/gene knowledge, and `web` for generic recency-aware external search.
Input schema JSON:
{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "query": {
      "type": "string",
      "maxLength": 600
    },
    "topic": {
      "type": "string",
      "maxLength": 240
    },
    "message": {
      "type": "string",
      "maxLength": 1200
    },
    "source": {
      "$ref": "#/$defs/literature_source"
    },
    "sources": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/literature_source"
      },
      "maxItems": 6
    },
    "limit": {
      "type": "integer",
      "minimum": 1,
      "maximum": 25
    },
    "max_per_source": {
      "type": "integer",
      "minimum": 1,
      "maximum": 10
    },
    "allow_web_fallback": {
      "type": "boolean"
    },
    "prefer_recent": {
      "type": "boolean"
    },
    "parser_payload": {
      "$ref": "#/$defs/parser_payload"
    }
  }
}

Tool: paper-download
Description: Use this tool when the user wants a paper PDF downloaded into app storage. `download` performs the full flow in one call, first extracting candidate PDF URLs from the provided fields and then streaming the PDF with progress tracking. `start` begins the download in the background so the caller can poll with `status`. When direct bot fetching is blocked, the tool should fall back to a browser-assisted session, optionally simulate a one-click download, let the user click the site download button if needed, and close the browser session after the file is saved.
Input schema JSON:
{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "action": {
      "type": "string",
      "enum": [
        "download",
        "start",
        "status"
      ]
    },
    "download_id": {
      "type": "string",
      "minLength": 1,
      "maxLength": 160
    },
    "paper_pdf_url": {
      "type": "string"
    },
    "pdf_url": {
      "type": "string"
    },
    "page_url": {
      "type": "string"
    },
    "candidate_urls": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "maxItems": 24
    },
    "page_html": {
      "type": "string",
      "maxLength": 400000
    },
    "message": {
      "type": "string",
      "maxLength": 12000
    },
    "paper_title": {
      "type": "string"
    },
    "file_name": {
      "type": "string",
      "maxLength": 240
    },
    "linked_type": {
      "type": "string",
      "maxLength": 80
    },
    "linked_name": {
      "type": "string",
      "maxLength": 220
    },
    "storage_path": {
      "type": "string",
      "maxLength": 2000
    },
    "timeout_ms": {
      "type": "integer",
      "minimum": 1000,
      "maximum": 120000
    },
    "use_browser_fallback": {
      "type": "boolean"
    },
    "simulate_one_click": {
      "type": "boolean"
    },
    "request_headers": {
      "type": "object",
      "additionalProperties": {
        "type": "string"
      }
    }
  }
}

Tool: paper-analysis
Description: Use this tool when the user asks to summarize a paper, extract the important findings, explain methods, or pull a protocol candidate out of paper text. Provide the richest available paper context through `paper`, `paper_summary`, `paper_abstract`, or `paper_text`. Set `extract_protocol` when the user explicitly wants procedural extraction, and set `generate_protocol` when the extracted methods should also be converted into an import-ready protocol JSON record.
Input schema JSON:
{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "paper": {
      "$ref": "#/$defs/paper_record"
    },
    "paper_title": {
      "type": "string"
    },
    "paper_summary": {
      "type": "string"
    },
    "paper_abstract": {
      "type": "string"
    },
    "paper_text": {
      "type": "string"
    },
    "message": {
      "type": "string"
    },
    "extract_protocol": {
      "type": "boolean"
    },
    "generate_protocol": {
      "type": "boolean"
    },
    "protocol_title_hint": {
      "type": "string"
    }
  }
}

Tool: protocol-generation
Description: Use this tool when the agent already has method evidence and needs to synthesize it into the app's import-ready protocol JSON format. It is best for converting extracted paper methods, structured step seeds, or summarized procedures into a protocol with materials, steps, placeholders, timestamps, and troubleshooting text. Provide `method_text`, `steps`, and `materials` when available, plus `title` or `protocol_title_hint` to guide the resulting protocol name.
Input schema JSON:
{
  "type": "object",
  "additionalProperties": false,
  "properties": {
    "title": {
      "type": "string"
    },
    "protocol_title_hint": {
      "type": "string"
    },
    "purpose": {
      "type": "string"
    },
    "method_text": {
      "type": "string"
    },
    "source_paper_title": {
      "type": "string"
    },
    "source_summary": {
      "type": "string"
    },
    "message": {
      "type": "string"
    },
    "materials": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "maxItems": 40
    },
    "steps": {
      "type": "array",
      "items": {
        "anyOf": [
          {
            "type": "string"
          },
          {
            "$ref": "#/$defs/protocol_generation_step"
          }
        ]
      },
      "maxItems": 40
    }
  }
}

